mat<3,3> result;
double det = m.det();
assert(std::abs(det) > 1e-10); // Check if matrix is invertible
double inv_det = 1.0 / det;

// Calculate the adjugate matrix and multiply by inverse determinant
for (int i = 0; i < 3; i++) {
    for (int j = 0; j < 3; j++) {
        // Cofactor calculation: (-1)^(i+j) * M_ij where M_ij is the minor
        result[i][j] = m.cofactor(j, i) * inv_det;
    }
}

return result;

